.mjms-pdf-viewer .pdf-rename-actions { display: flex; justify-content: flex-end; gap: 8px; }

.mjms-pdf-viewer .pdf-rename-dialog { position: fixed; inset: 0; margin: auto; height: fit-content; overflow: auto; }

