.mjms-pdf-viewer .pdf-rename-error { margin: 4px 12px; color: var(--color-error); }

/* Keep Nextcloud header flex layout from compressing the inline filename input. */
.mjms-pdf-viewer .pdf-toolbar .pdf-rename-form {
  flex: 0 0 auto;
  width: auto;
  margin: 0;
}
.mjms-pdf-viewer .pdf-toolbar .pdf-rename-form input {
  flex: 0 0 clamp(180px, 18vw, 260px);
  width: clamp(180px, 18vw, 260px);
  min-width: 180px;
  max-width: none;
}

/* Keep the Manager entry first and prevent the rename field from squeezing it. */
.mjms-pdf-viewer .pdf-manager-link {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid var(--color-primary-element);
  border-radius: var(--border-radius);
  background: var(--color-primary-element);
  color: var(--color-primary-element-text);
  text-decoration: none;
  white-space: nowrap;
}
.mjms-pdf-viewer .pdf-manager-link:hover { filter: brightness(.95); }

