.mjms-pdf-viewer .pdf-toolbar { flex-wrap: nowrap; overflow-x: auto; min-height: 54px; }
.mjms-pdf-viewer .pdf-toolbar > * { flex-shrink: 0; }
.mjms-pdf-viewer .pdf-file-navigation { flex-wrap: nowrap; align-items: center; }

/* The editable filename already identifies the document in our toolbar. */
#viewer[data-handler="mjms-pdf-viewer"] .modal-header__name { display: none !important; }
.mjms-pdf-viewer .pdf-rename-error {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 8px 12px;
  padding: 14px 18px;
  border: 2px solid var(--color-error, #b00020);
  border-radius: var(--border-radius, 6px);
  background: var(--color-error, #b00020);
  color: var(--color-error-text, #fff);
  font-size: 16px;
  line-height: 1.5;
  box-shadow: 0 2px 8px #0003;
}
.mjms-pdf-viewer .pdf-rename-error strong { font-size: 18px; font-weight: 700; }
.mjms-pdf-viewer .pdf-rename-form input[aria-invalid="true"] { border: 2px solid var(--color-error, #b00020); }

