  --mjms-toolbar-height: 64px;
  --mjms-native-actions-width: 160px;
}
#viewer[data-handler="mjms-pdf-viewer"] .modal-wrapper .modal-container {
  top: 0 !important;
}
#viewer[data-handler="mjms-pdf-viewer"] .modal-header {
  position: absolute !important;
  inset: 0 0 auto auto !important;
  width: var(--mjms-native-actions-width) !important;
  height: var(--mjms-toolbar-height) !important;
  min-height: var(--mjms-toolbar-height);
  display: flex !important;
  align-items: center;
  justify-content: flex-end;
  padding: 8px;
  z-index: 10;
  box-sizing: border-box;
}
#viewer[data-handler="mjms-pdf-viewer"] .modal-header .icons-menu {
  position: static !important;
  display: flex;
  align-items: center;
  margin: 0;
}
#viewer[data-handler="mjms-pdf-viewer"] .pdf-toolbar {
  width: calc(100% - var(--mjms-native-actions-width));
  height: var(--mjms-toolbar-height);
  min-height: var(--mjms-toolbar-height);
  max-height: var(--mjms-toolbar-height);
  flex: 0 0 var(--mjms-toolbar-height);
  flex-wrap: nowrap;
  white-space: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
}
